input.command:
cd <run-dir>; sqlite3 warehouse.db "select distinct status from fct_policy_premium; select min(eff_dt),max(eff_dt) from fct_policy_premium; select distinct status, severity from fct_claims; select closed_dt from fct_claims where closed_dt is not null limit 3;
select g.region, round(sum(premium_amt)-sum(cancellation_amt),2) from fct_policy_premium p join dim_geography g using(geo_id) where status!='quote' and eff_dt>='2026-07-01' and eff_dt<'2026-10-01' group by 1;
select d.product_line, round(sum(premium_amt),2) from fct_policy_premium p join dim_product d using(product_id) where status!='quote' and eff_dt>='2026-01-01' and eff_dt<'2026-07-01' group by 1;
select count(distinct policy_id) from fct_policy_premium where status!='quote' and eff_dt>='2026-03-01' and eff_dt<'2026-04-01';
select severity, round(sum(paid_amt),2) from fct_claims where status='closed' and closed_dt>='2026-04-01' and closed_dt<'2026-07-01' group by 1;
select count(*) from fct_policy_premium where geo_id not in (select geo_id from dim_geography) or product_id not in (select product_id from dim_product);
select typeof(eff_dt), length(eff_dt), count(*) from fct_policy_premium group by 1,2;
select sum(cancellation_amt is null), sum(premium_amt is null) from fct_policy_premium;"

